INSERT INTO `t_d_criteria` VALUES (3488,75,1,1,'1',1,NULL,NULL,NULL,'machine','Клинични критерии:');
INSERT INTO `t_d_criteria` VALUES (3489,75,2,2,'1.1',2,NULL,NULL,NULL,'machine','всяко лице с повишена температура или с предишни случаи на повишена температура;');
INSERT INTO `t_d_criteria` VALUES (3490,75,3,2,'1.2',3,1,'AND',NULL,'machine','поне един от следните три симптома:');
