INSERT INTO `t_d_criteria` VALUES (3492,75,5,3,'1.2.2',2,NULL,NULL,NULL,'machine','затруднения в дишането;');
INSERT INTO `t_d_criteria` VALUES (3493,75,6,3,'1.2.3',2,NULL,NULL,NULL,'machine','задух;');
INSERT INTO `t_d_criteria` VALUES (3494,75,7,2,'1.3',3,1,'AND',NULL,'machine','поне един от следните четири критерия:');
INSERT INTO `t_d_criteria` VALUES (3495,75,8,3,'1.3.1',2,NULL,NULL,NULL,'machine','радиографски данни за пневмония;');
INSERT INTO `t_d_criteria` VALUES (3496,75,9,3,'1.3.2',2,NULL,NULL,NULL,'machine','радиографски данни за тежък остър респираторен синдром;');
INSERT INTO `t_d_criteria` VALUES (3497,75,10,3,'1.3.3',2,NULL,NULL,NULL,'machine','резултати от аутопсия, констатиращи пневмония;');
INSERT INTO `t_d_criteria` VALUES (3498,75,11,3,'1.3.4',2,NULL,NULL,NULL,'machine','резултати от аутопсия, констатиращи тежък остър респираторен синдром;');
INSERT INTO `t_d_criteria` VALUES (3499,75,12,2,'1.4',2,NULL,'AND',NULL,'machine','липса на алтернативна диагноза, която да може напълно да обясни заболяването.');
INSERT INTO `t_d_criteria` VALUES (3500,75,13,1,'2',1,NULL,NULL,NULL,'machine','Лабораторни критерии:');
INSERT INTO `t_d_criteria` VALUES (3501,75,14,2,'2.1',2,NULL,NULL,NULL,'machine','Лабораторни критерии за потвърждаване на случай:');
INSERT INTO `t_d_criteria` VALUES (3502,75,15,3,'2.1.1',3,1,NULL,NULL,'machine','Поне един от следните три критерия:');
INSERT INTO `t_d_criteria` VALUES (3503,75,16,4,'2.1.1.1',2,NULL,NULL,NULL,'machine','изолиране на вирус в клетъчна култура от клинична проба и идентифициране на SARS-CoV чрез метод от рода на обратно транскриптазна полимеразна верижна реакция (RT-PCR);');
INSERT INTO `t_d_criteria` VALUES (3504,75,17,4,'2.1.1.2',3,1,NULL,NULL,'machine','откриване на нуклеинова киселина на SARS-CoV в поне една от следните три ситуации:');
INSERT INTO `t_d_criteria` VALUES (3505,75,18,5,'2.1.1.2.1',2,NULL,NULL,NULL,'machine','в поне две различни клинични проби (напр. назофарингеален секрет и изпражнения);');
INSERT INTO `t_d_criteria` VALUES (3506,75,19,5,'2.1.1.2.2',2,NULL,NULL,NULL,'machine','в същия вид клинична проба, взета два или повече пъти по време на заболяването (напр. поредица назофарингеални аспирати);');
INSERT INTO `t_d_criteria` VALUES (3507,75,20,5,'2.1.1.2.3',2,NULL,NULL,NULL,'machine','две различни изследвания или повторено изследване RT-PCR с използване на нов екстрат РНК от първоначалната клинична проба при всеки тест;');
INSERT INTO `t_d_criteria` VALUES (3508,75,21,4,'2.1.1.3',2,NULL,NULL,NULL,'machine','специфичен антитяло-отговор срещу SARS-CoV, получен чрез един от следните два метода:');
INSERT INTO `t_d_criteria` VALUES (3509,75,22,5,'2.1.1.3.1',2,NULL,NULL,NULL,'machine','сероконверсия чрез ELISA или индиректен имунофлуоресцентен антитяло тест (IFA) в серума в острата фаза и във фазата на възстановяване, изследвани едновременно;');
INSERT INTO `t_d_criteria` VALUES (3510,75,23,5,'2.1.1.3.2',2,NULL,NULL,NULL,'machine','четирикратно или по-голямо нарастване на титъра на антителата между серума в острата фаза и във фазата на възстановяване, изследвани едновременно.');
INSERT INTO `t_d_criteria` VALUES (3511,75,24,2,'2.2',2,NULL,NULL,NULL,'machine','Лабораторни критерии за вероятен случай:');
INSERT INTO `t_d_criteria` VALUES (3512,75,25,3,'2.2.1',3,1,NULL,NULL,'machine','Поне един от следните два критерия:');
INSERT INTO `t_d_criteria` VALUES (3513,75,26,4,'2.2.1.1',2,NULL,NULL,NULL,'machine','единичен положителен тест за антитела за SARS-CoV;');
INSERT INTO `t_d_criteria` VALUES (3514,75,27,4,'2.2.1.2',2,NULL,NULL,NULL,'machine','положителен резултат при полимеразна верижна реакция (PCR) за SARS-CoV в единична клинична проба и едно изследване.');
INSERT INTO `t_d_criteria` VALUES (3515,75,28,1,'3',1,NULL,NULL,NULL,'machine','Епидемиологични критерии:');
INSERT INTO `t_d_criteria` VALUES (3516,75,29,2,'3.1',3,1,NULL,NULL,'machine','Поне един от следните три критерия:');
INSERT INTO `t_d_criteria` VALUES (3517,75,30,3,'3.1.1',3,1,NULL,NULL,'machine','всяко лице с поне едно от следните три условия:');
INSERT INTO `t_d_criteria` VALUES (3518,75,31,4,'3.1.1.1',2,NULL,NULL,NULL,'machine','лице, заемащо длъжност, свързана с повишен риск от излагане на SARS-CoV (напр. персонал в лаборатория, работеща с живи вируси на SARS-CoV или живи вируси от същия тип или съхраняваща клинични проби, заразени със SARS-CoV; лице в контакт с диви животни или с други животни, смятани за източник на SARS-CoV, с техните изпражнения, секрети и т.н.);');
INSERT INTO `t_d_criteria` VALUES (3519,75,32,4,'3.1.1.2',2,NULL,NULL,NULL,'machine','близко лице* на едно или повече лица, при което(ито) ТОРС е потвърден или което(ито) е(са) подложено(и) на изследвания, свързани с ТОРС;');
INSERT INTO `t_d_criteria` VALUES (3520,75,33,4,'3.1.1.3',2,NULL,NULL,NULL,'machine','лице, което е пътувало или пребивавало в район, засегнат от ТОРС;');
INSERT INTO `t_d_criteria` VALUES (3521,75,34,3,'3.1.2',2,NULL,NULL,NULL,'machine','двама или повече здравни работници** в едно и също лечебно заведение с клинични признаци на ТОРС, при които заболяването се е проявило внезапно в рамките на един и същ 10-дневен период;');
INSERT INTO `t_d_criteria` VALUES (3522,75,35,3,'3.1.3',2,NULL,NULL,NULL,'machine','три или повече лица (здравни работници и/или пациенти, и/или посетители) с клинични признаци на ТОРС, при които заболяването се е проявило внезапно в рамките на един и същ 10-дневен период и при които има епидемична връзка с лечебното заведение.');
INSERT INTO `t_d_criteria` VALUES (3523,75,36,3,NULL,2,NULL,NULL,'unnumbered','machine','-------------- * За близко се смята лице, което се грижи за болен от ТОРС, живее с него или е имало пряк контакт с неговите респираторни секрети, телесни течности и/или екскрети (напр. фекалии).');
INSERT INTO `t_d_criteria` VALUES (3524,75,37,3,NULL,2,NULL,NULL,'unnumbered','machine','** В този контекст понятието \"здравен работник\" обхваща целия болничен персонал. Определението за \"лечебно заведение\", в което възниква поредицата от случаи, ще зависи от местната ситуация. Размерът на заведението може да варира от самостоятелно, дори и малко, лечебно заведение до отделно отделение или отделение в голяма болница.');
INSERT INTO `t_d_criteria` VALUES (3681,15,1,1,'1',1,NULL,NULL,NULL,'machine','Клинични критерии:');
INSERT INTO `t_d_criteria` VALUES (3682,15,2,2,'1.1',3,1,NULL,NULL,'machine','Всяко лице с поне един от следните два симптома:');
INSERT INTO `t_d_criteria` VALUES (3683,15,3,3,'1.1.1',2,NULL,NULL,NULL,'machine','повишена температура; и');
INSERT INTO `t_d_criteria` VALUES (3684,15,4,3,'1.1.2',2,NULL,NULL,NULL,'machine','везикули или твърди пустули, които се намират в еднакъв стадий на развитие и са разположени центробежно;');
INSERT INTO `t_d_criteria` VALUES (3685,15,5,2,'1.2',3,1,NULL,NULL,'machine','Атипични форми, изразяващи се в поне един от следните четири симптома:');
INSERT INTO `t_d_criteria` VALUES (3686,15,6,3,'1.2.1',2,NULL,NULL,NULL,'machine','хеморагични лезии;');
INSERT INTO `t_d_criteria` VALUES (3687,15,7,3,'1.2.2',2,NULL,NULL,NULL,'machine','плоски меки лезии, непрогресиращи към везикули;');
INSERT INTO `t_d_criteria` VALUES (3688,15,8,3,'1.2.3',2,NULL,NULL,NULL,'machine','вариола без ерупции;');
INSERT INTO `t_d_criteria` VALUES (3689,15,9,3,'1.2.4',2,NULL,NULL,NULL,'machine','лека форма.');
INSERT INTO `t_d_criteria` VALUES (3690,15,10,1,'2',1,NULL,NULL,NULL,'machine','Лабораторни критерии:');
INSERT INTO `t_d_criteria` VALUES (3691,15,11,2,'2.1',3,1,NULL,NULL,'machine','Лабораторни критерии за потвърден случай: поне едно от следните две лабораторни изследвания:');
INSERT INTO `t_d_criteria` VALUES (3692,15,12,3,'2.1.1',2,NULL,NULL,NULL,'machine','изолиране на вирус на вариола от клинична проба и последващо секвениране (само в лаборатории, определени като Р4);');
INSERT INTO `t_d_criteria` VALUES (3693,15,13,3,'2.1.2',2,NULL,NULL,NULL,'machine','доказване на нуклеинова киселина на вирус на вариола в клинична проба и последващо секвениране.');
INSERT INTO `t_d_criteria` VALUES (3694,15,14,3,NULL,2,NULL,NULL,'unnumbered','machine','Лабораторните резултати трябва да бъдат разглеждани в съответствие с ваксиналния статус.');
INSERT INTO `t_d_criteria` VALUES (3695,15,15,2,'2.2',2,NULL,NULL,NULL,'machine','Лабораторни критерии за вероятен случай:');
INSERT INTO `t_d_criteria` VALUES (3696,15,16,3,'2.2.1',2,NULL,NULL,NULL,'machine','идентифициране на частици ортопокс вирус посредством електронна микроскопия.');
INSERT INTO `t_d_criteria` VALUES (3697,15,17,1,'3',1,1,NULL,NULL,'machine','Епидемиологични критерии: поне една от следните две епидемични връзки:');
INSERT INTO `t_d_criteria` VALUES (3698,15,18,2,'3.1',2,NULL,NULL,NULL,'machine','предаване от човек на човек;');
INSERT INTO `t_d_criteria` VALUES (3699,15,19,2,'3.2',2,NULL,NULL,NULL,'machine','излагане на въздействие в лаборатория (когато съществува риск от експозиция на вируса на вариола).');
INSERT INTO `t_d_criteria` VALUES (3772,42,1,1,'1',1,NULL,NULL,NULL,'machine','Клинични критерии: неприложимо за целите на надзора.');
INSERT INTO `t_d_criteria` VALUES (3773,42,2,1,'2',1,NULL,NULL,NULL,'machine','Лабораторни критерии:');
INSERT INTO `t_d_criteria` VALUES (3774,42,3,2,'2.1',3,1,NULL,NULL,'machine','Поне един от следните три критерия:');
INSERT INTO `t_d_criteria` VALUES (3775,42,4,3,'2.1.1',2,NULL,NULL,NULL,'machine','изолиране на S. pneumoniae от проба от място, което нормално е стерилно;');
INSERT INTO `t_d_criteria` VALUES (3776,42,5,3,'2.1.2',2,NULL,NULL,NULL,'machine','доказване на нуклеинова киселина на S. pneumoniae в проба от място, което нормално е стерилно;');
INSERT INTO `t_d_criteria` VALUES (3777,42,6,3,'2.1.3',2,NULL,NULL,NULL,'machine','доказване на антиген на S. pneumoniae в проба от място, което нормално е стерилно.');
INSERT INTO `t_d_criteria` VALUES (3778,42,7,1,'3',1,NULL,NULL,NULL,'machine','Епидемиологични критерии: не е приложимо.');
INSERT INTO `t_d_criteria` VALUES (3804,71,1,1,'1',1,NULL,NULL,NULL,'machine','Клинични критерии (СПИН):');
INSERT INTO `t_d_criteria` VALUES (3805,71,2,2,'1.1',2,NULL,NULL,NULL,'machine','Всяко лице с някоя от клиничните прояви, описани в европейското определение за случаите на СПИН за:');
INSERT INTO `t_d_criteria` VALUES (3806,71,3,3,'1.1.1',2,NULL,NULL,NULL,'machine','възрастни или подрастващи на възраст 15 години или повече;');
INSERT INTO `t_d_criteria` VALUES (3807,71,4,3,'1.1.2',2,NULL,NULL,NULL,'machine','деца под 15 години.');
INSERT INTO `t_d_criteria` VALUES (3808,71,5,1,'2',1,NULL,NULL,NULL,'machine','Лабораторни критерии (ХИВ):');
INSERT INTO `t_d_criteria` VALUES (3809,71,6,2,'2.1',2,NULL,NULL,NULL,'machine','Възрастни, подрастващи и деца на възраст 18 месеца или повече.');
INSERT INTO `t_d_criteria` VALUES (3810,71,7,3,'2.1.1',3,1,NULL,NULL,'machine','Поне един от следните три критерия:');
INSERT INTO `t_d_criteria` VALUES (3811,71,8,4,'2.1.1.1',2,NULL,NULL,NULL,'machine','положителен резултат от тест за откриване на антитела срещу ХИВ или комбинирано скринингово изследване (антитела срещу ХИВ и р24 антиген на ХИВ), потвърдено от по-специфичен тест за антитела (напр. Western blot);');
INSERT INTO `t_d_criteria` VALUES (3812,71,9,4,'2.1.1.2',2,NULL,NULL,NULL,'machine','положителен резултат от два имуноензимни теста (EIA) за откриване на антитела, потвърдени от по-специфичен тест за антитела (напр.');
INSERT INTO `t_d_criteria` VALUES (3813,71,10,4,NULL,2,NULL,NULL,'unnumbered','machine','Western blot);');
INSERT INTO `t_d_criteria` VALUES (3814,71,11,4,'2.1.1.3',3,1,NULL,NULL,'machine','положителен резултат от две отделни проби от поне едно от следните три:');
INSERT INTO `t_d_criteria` VALUES (3815,71,12,5,'2.1.1.3.1',2,NULL,NULL,NULL,'machine','откриване на нуклеинова киселина на вируса на ХИВ (ХИВ-РНК, ХИВ-ДНК);');
INSERT INTO `t_d_criteria` VALUES (3816,71,13,5,'2.1.1.3.2',2,NULL,NULL,NULL,'machine','доказване на вируса на ХИВ чрез тест за откриване на р24 антиген на вируса на ХИВ, включващ проба за неутрализация;');
INSERT INTO `t_d_criteria` VALUES (3817,71,14,5,'2.1.1.3.3',2,NULL,NULL,NULL,'machine','изолиране на вируса на ХИВ.');
INSERT INTO `t_d_criteria` VALUES (3818,71,15,2,'2.2',2,NULL,NULL,NULL,'machine','Деца под 18-месечна възраст:');
INSERT INTO `t_d_criteria` VALUES (3819,71,16,3,'2.2.1',3,1,NULL,NULL,'machine','Положителни резултати от две отделни проби (без кръв от пъпната връв) от поне едно от следните три:');
INSERT INTO `t_d_criteria` VALUES (3820,71,17,4,'2.2.1.1',2,NULL,NULL,NULL,'machine','изолиране на вируса на ХИВ;');
INSERT INTO `t_d_criteria` VALUES (3821,71,18,4,'2.2.1.2',2,NULL,NULL,NULL,'machine','откриване на нуклеинова киселина на вируса на ХИВ (ХИВ-РНК, ХИВ-ДНК);');
INSERT INTO `t_d_criteria` VALUES (3822,71,19,4,'2.2.1.3',2,NULL,NULL,NULL,'machine','доказване на вируса на ХИВ чрез тест за откриване на р24 антиген на вируса на ХИВ, включително реакция неутрализация при деца на възраст един месец или повече.');
INSERT INTO `t_d_criteria` VALUES (3823,71,20,1,'3',1,NULL,NULL,NULL,'machine','Епидемиологични критерии: не е приложимо.');
INSERT INTO `t_d_criteria` VALUES (3829,82,1,1,'1',1,NULL,NULL,NULL,'machine','Клинични критерии:');
INSERT INTO `t_d_criteria` VALUES (3830,82,2,2,'1.1',3,1,NULL,NULL,'machine','Всяко лице с поне една от следните клинични форми:');
