INSERT INTO `t_d_criteria` VALUES (4942,53,2,1,NULL,2,NULL,NULL,'unnumbered','machine','Всяко лице с еритемна кожна лезия (Еритема мигранс) на мястото, където е бил впит кърлеж, развитие на регионален лимфангит и лимфаденит и последващо стадийно засягане на следните органи и системи:');
INSERT INTO `t_d_criteria` VALUES (4943,53,3,2,'1.1',2,NULL,NULL,NULL,'machine','Опорно-двигателна система: рекурентни епизоди от отоци и болки в една или повече от големите стави;');
INSERT INTO `t_d_criteria` VALUES (4944,53,4,2,'1.2',2,NULL,NULL,NULL,'machine','Сърце: остро настъпили ритъмни нарушения (A-V блок I - III степен), рядко миокардит и панкардит;');
INSERT INTO `t_d_criteria` VALUES (4945,53,5,2,'1.3',2,NULL,NULL,NULL,'machine','Очи: конюнктивит, увеит, папилит, еписклерит, кератит.');
INSERT INTO `t_d_criteria` VALUES (4946,53,6,2,NULL,2,NULL,NULL,'unnumbered','machine','Забележка. При клинични изяви, характеризиращи се със засягане на нервната система при възрастни и при деца, докладването се извършва съобразно дефиницията за случай на Лаймска невроборелиоза.');
INSERT INTO `t_d_criteria` VALUES (4947,53,7,1,'2',1,NULL,NULL,NULL,'machine','Лабораторни критерии съобразно стадия на заболяването:');
INSERT INTO `t_d_criteria` VALUES (4948,53,8,2,'2.1',2,NULL,NULL,NULL,'machine','доказване на специфични антитела срещу B. burgdorferi;');
