INSERT INTO `t_d_criteria` VALUES (5031,58,19,1,'2',1,NULL,NULL,NULL,'machine','Лабораторни критерии:');
INSERT INTO `t_d_criteria` VALUES (5032,58,20,2,'2.1',3,1,NULL,NULL,'machine','Поне един от следните два критерия:');
INSERT INTO `t_d_criteria` VALUES (5033,58,21,3,'2.1.1',2,NULL,NULL,NULL,'machine','изолиране на Listeria monocytogenes или откриване на нуклеинова киселина на Listeria monocytogenes от място, което нормално е стерилно;');
INSERT INTO `t_d_criteria` VALUES (5034,58,22,3,'2.1.2',2,NULL,NULL,NULL,'machine','също така при случай, свързан с бременност: изолиране на Listeria monocytogenes или откриване на нуклеинова киселина на Listeria monocytogenes от място, което нормално е нестерилно (напр. тъкан от плацентата, амниотична течност, мекониум, вагинална натривка), или от плод, от мъртвородено дете, от новородено или от майката.');
