INSERT INTO `t_d_criteria` VALUES (5114,65,7,3,'2.1.2',3,0,NULL,'require-unknown','machine','полиовирус от ваксинален произход (ПВП) (при ПВП поне 85% сходство с ваксиналния полиовирус в нуклеотидната секвенция на протеина на VP1 секцията);');
INSERT INTO `t_d_criteria` VALUES (5115,65,8,3,'2.1.3',2,NULL,NULL,NULL,'machine','полиовирус от типа Сейбин: вътрешнотипова диференциация, осъществена от акредитирана от СЗО лаборатория за полиомиелит (при полиовирус от ваксинален произход разлика в секвенцията на протеина VP1 в сравнение с ваксиналния вирус от същия серотип от над 1% до максимум 15%).');
INSERT INTO `t_d_criteria` VALUES (5116,65,9,1,'3',1,NULL,NULL,NULL,'machine','Епидемиологични критерии:');
