INSERT INTO `t_d_criteria` VALUES (5119,65,12,3,'3.1.2',2,NULL,NULL,NULL,'machine','предишни пътувания в ендемична за полиомиелит област или в област, в която е предполагаемо или потвърдено разпространението на полиовирус.');
INSERT INTO `t_d_criteria` VALUES (5126,67,1,1,'1',1,NULL,NULL,NULL,'machine','Клинични критерии:');
INSERT INTO `t_d_criteria` VALUES (5127,67,2,2,'1.1',2,NULL,NULL,NULL,'machine','Всяко лице със заболяване, което се характеризира с остро начало, повишена температура, гадене, повръщане и водниста диария,');
INSERT INTO `t_d_criteria` VALUES (5128,67,3,2,'1.2',2,NULL,'AND',NULL,'machine','при деца: диария (3 или повече редки или воднисти изхождания за 24 часа) и/или повръщане (1 или повече за 24 часа), което в тежките случаи може да доведе до обезводняване и загуба на електролити от организма.');
INSERT INTO `t_d_criteria` VALUES (5129,67,4,1,'2',1,NULL,NULL,NULL,'machine','Лабораторни критерии:');
