INSERT INTO `t_d_criteria` VALUES (5210,72,13,3,NULL,2,NULL,NULL,'unnumbered','machine','Следва да се отбележи, че очни и неврологични прояви може да възникнат на всеки един стадий на сифилис.');
INSERT INTO `t_d_criteria` VALUES (5211,72,14,2,'1.4',2,NULL,NULL,NULL,'machine','Късен латентен сифилис (над 1 година):');
