INSERT INTO `t_d_criteria` VALUES (5217,72,20,3,'2.1.3',2,NULL,NULL,NULL,'machine','доказване на Treponema в ексудати от лезия или тъкани чрез техники за амплификация на нуклеинова киселина;');
INSERT INTO `t_d_criteria` VALUES (5218,72,21,3,'2.1.4',2,NULL,NULL,NULL,'machine','откриване на антитела срещу Treponema pallidum чрез скринингов тест (TPHA, TPPA или EIA) и допълнително откриване или на антитела TP-IgM (напр. чрез IgM-ELISA, IgM имуноблот или 19S-IgM-FTA-abs), или на нетрепонемни антитела (напр. RPR, VDRL).');
