INSERT INTO `t_d_criteria` VALUES (5382,88,2,2,'1.1',3,1,NULL,NULL,'machine','необясним обрив по която и да е част от тялото и най-малко един от следните симптоми - повишена телесна температура (обикновено > 38,5°С); главоболие; болки в гърба; умора; локализирана или генерализирана лимфаденопатия,');
INSERT INTO `t_d_criteria` VALUES (5383,88,3,2,'1.2',3,1,'OR',NULL,'machine','необясним генерализиран или локализиран макулопапулозен или везикулопустулозен обрив с центробежно разпространение, с лезии с умбиликация или струпеи и най-малко един от следните симптоми - повишена телесна температура (обикновено > 38,5°С); главоболие; болки в гърба; умора; локализирана или генерализирана лимфаденопатия.');
INSERT INTO `t_d_criteria` VALUES (5384,88,4,1,'2',1,NULL,NULL,NULL,'machine','Лабораторни критерии:');
INSERT INTO `t_d_criteria` VALUES (5385,88,5,2,'2.1',2,NULL,NULL,NULL,'machine','положителен резултат от PCR изследване, специфично за вируса на маймунска вариола,');
INSERT INTO `t_d_criteria` VALUES (5386,88,6,2,'2.2',2,NULL,'OR',NULL,'machine','положителен резултат от специфично за ортопоксвирус PCR изследване, което след това се потвърждава чрез определяне на нуклеотидна последователност на открития вирус като вируса на маймунска вариола с начало на симптомите след 28 февруари 2022 г.');
INSERT INTO `t_d_criteria` VALUES (5387,88,7,1,'3',1,1,NULL,NULL,'machine','Епидемиологични критерии - най-малко една от следните епидемиологични връзки:');
INSERT INTO `t_d_criteria` VALUES (5388,88,8,2,'3.1',2,NULL,NULL,NULL,'machine','близък контакт с потвърден или вероятен случай на маймунска вариола до 21 дни преди появата на симптомите;');
INSERT INTO `t_d_criteria` VALUES (5389,88,9,2,'3.2',2,NULL,NULL,NULL,'machine','пътуване до ендемични за маймунска вариола държави до 21 дни преди появата на симптомите;');
INSERT INTO `t_d_criteria` VALUES (5390,88,10,2,'3.3',2,NULL,NULL,NULL,'machine','наличие на множество или анонимни сексуални партньори до 21 дни преди появата на симптомите;');
