INSERT INTO `t_d_criteria` VALUES (5602,10,12,3,'2.1.5',2,NULL,NULL,NULL,'machine','деменция.');
INSERT INTO `t_d_criteria` VALUES (5603,10,13,1,'3',2,NULL,NULL,NULL,'machine','Критерии за диагностициране:');
INSERT INTO `t_d_criteria` VALUES (5604,10,14,2,'3.1',2,NULL,NULL,NULL,'machine','Диагностични критерии за потвърждаване на случай: невропатологично потвърждаване: спонгиформна промяна и значително отлагане на прионов белтък с ясно изразени плаки навсякъде в големия и малкия мозък.');
INSERT INTO `t_d_criteria` VALUES (5605,10,15,2,'3.2',2,NULL,NULL,NULL,'machine','Диагностични критерии за вероятен или възможен случай:');
INSERT INTO `t_d_criteria` VALUES (5606,10,16,3,'3.2.1',2,NULL,NULL,NULL,'machine','електроенцефалографията (ЕЕГ) не показва типична картина (типичната картина при ЕЕГ на спорадичната CJD се състои в генерализирани периодични комплекси, приблизително по един на секунда; те могат понякога да бъдат наблюдавани и в по-късни стадии на варианта на CJD) на спорадична Болест на Кройцфелд-Якоб в ранния стадий на болестта;');
INSERT INTO `t_d_criteria` VALUES (5607,10,17,3,'3.2.2',2,NULL,NULL,NULL,'machine','изследването на мозъка с ядрено-магнитен резонанс показва двустранно хиперинтензни огнища в пулвинарните структури на мозъка;');
INSERT INTO `t_d_criteria` VALUES (5608,10,18,3,'3.2.3',2,NULL,NULL,NULL,'machine','има положителен резултат от биопсия на сливиците (не се препоръчва използване на биопсия на сливиците нито като рутинно изследване, нито в случаите, когато при ЕЕГ се наблюдават типични прояви на спорадична CJD, но тя може да бъде полезна при случаите, при които има съмнение, клиничните характеристики са съвместими с вариант на CJD и ядрено-магнитният резонанс не показва хиперинтензни огнища в пулвинарните структури).');
INSERT INTO `t_d_criteria` VALUES (5609,10,19,1,'4',1,NULL,NULL,NULL,'machine','Епидемиологични критерии:');
INSERT INTO `t_d_criteria` VALUES (5610,10,20,2,'4.1',2,NULL,NULL,'accepted-auto','machine','Епидемична връзка на предаване от човек на човек (напр. преливане на кръв).');
INSERT INTO `t_d_criteria` VALUES (5611,16,1,1,'1',1,NULL,NULL,NULL,'machine','Клинични критерии:');
INSERT INTO `t_d_criteria` VALUES (5612,16,2,2,NULL,2,NULL,NULL,'accepted-auto','machine','Всяко лице със следните симптоми: остро начало, повишена температура, умерено увредено общо състояние и циклично развиващ се, придружен със сърбеж псевдополиморфен обрив (макули, папули, везикули, крусти). Обривът е разпространен по тялото, лицето и крайниците, задължително по окосмената част на главата и рядко се наблюдава по дланите и стъпалата. Единични обривни елементи се наблюдават и по лигавиците.');
INSERT INTO `t_d_criteria` VALUES (5613,16,3,1,'2',1,NULL,NULL,NULL,'machine','Лабораторни критерии:');
INSERT INTO `t_d_criteria` VALUES (5614,16,4,2,'2.1',2,NULL,NULL,NULL,'machine','доказване на антиген на вируса на варицелата;');
