INSERT INTO `t_d_criteria` VALUES (5616,16,6,2,'2.3',2,NULL,NULL,NULL,'machine','изолация на вируса;');
INSERT INTO `t_d_criteria` VALUES (5617,16,7,2,'2.4',2,NULL,NULL,NULL,'machine','доказване на нуклеинова киселина на вируса.');
INSERT INTO `t_d_criteria` VALUES (5618,16,8,1,'3',1,NULL,NULL,NULL,'machine','Епидемиологични критерии:');
