INSERT INTO `t_d_criteria` VALUES (5624,28,4,2,'2.1',2,NULL,NULL,NULL,'machine','изолиране на някои от бактериите, причиняващи гастроентерит/ентероколит (без Campylobacter, Salmonella, Shigella, патогенни E. Coli, Vibrio cholerae , Listeria, Yersinia enterocolitica);');
INSERT INTO `t_d_criteria` VALUES (5625,28,5,2,'2.2',2,NULL,NULL,NULL,'machine','биохимична идентификация на бактерии;');
