INSERT INTO `t_d_criteria` VALUES (5627,28,7,2,'2.4',2,NULL,NULL,NULL,'machine','доказване на антигени на някои от вирусите (без Rotavirus), причиняващи гастроентерит/ентероколит в клинични проби (Adenovirus, Norovirus, Astrovirus);');
