INSERT INTO `t_d_criteria` VALUES (5664,34,12,4,'2.2.1.5',2,NULL,NULL,NULL,'machine','сероконверсия или четирикратно повишение на титъра на антителата на специфични за Денга антитела в двойни серумни проби.');
