INSERT INTO `t_d_criteria` VALUES (5715,46,2,2,'1.1',2,NULL,NULL,NULL,'machine','Всяко лице с кашлица, продължаваща най-малко две седмици;');
INSERT INTO `t_d_criteria` VALUES (5716,46,3,2,'1.2',3,1,'AND',NULL,'machine','Поне един от следните три симптома:');
INSERT INTO `t_d_criteria` VALUES (5717,46,4,3,'1.2.1',2,NULL,NULL,NULL,'machine','пароксизмална кашлица;');
INSERT INTO `t_d_criteria` VALUES (5718,46,5,3,'1.2.2',2,NULL,NULL,NULL,'machine','инспираторен реприз;');
INSERT INTO `t_d_criteria` VALUES (5719,46,6,3,'1.2.3',2,NULL,NULL,NULL,'machine','повръщане след закашляне.');
INSERT INTO `t_d_criteria` VALUES (5720,46,7,2,'1.2',2,NULL,'OR','duplicate-path','machine','Всяко лице с поставена от лекар диагноза \"коклюш\";');
INSERT INTO `t_d_criteria` VALUES (5721,46,8,2,'1.3',2,NULL,'OR',NULL,'machine','Апноични паузи при кърмачета.');
INSERT INTO `t_d_criteria` VALUES (5722,46,9,2,NULL,2,NULL,NULL,'unnumbered','machine','При всички индивиди, в това число възрастни, подрастващи или ваксинирани деца, може да се проявяват атипични симптоми. Следва да се проучат характеристиките на кашлицата, особено дали е от пароксизмално естество, дали се засилва през нощта и дали се проявява, без да има повишена температура.');
INSERT INTO `t_d_criteria` VALUES (5723,46,10,1,'2',1,NULL,NULL,NULL,'machine','Лабораторни критерии:');
INSERT INTO `t_d_criteria` VALUES (5724,46,11,2,'2.1',3,1,NULL,NULL,'machine','Поне един от следните три критерия:');
INSERT INTO `t_d_criteria` VALUES (5725,46,12,3,'2.1.1',2,NULL,NULL,NULL,'machine','изолиране на Bordetella pertussis от клинична проба;');
INSERT INTO `t_d_criteria` VALUES (5726,46,13,3,'2.1.2',2,NULL,NULL,NULL,'machine','доказване на нуклеинова киселина на Bordetella pertussis в клинична проба;');
INSERT INTO `t_d_criteria` VALUES (5727,46,14,3,'2.1.3',2,NULL,NULL,NULL,'machine','доказване на специфичен антитяло-отговор срещу Bordetella pertussis.');
INSERT INTO `t_d_criteria` VALUES (5728,46,15,3,NULL,2,NULL,NULL,'unnumbered','machine','Директна диагноза (30.2.1.1 и 30.2.1.2): Bordetella pertussis и нейната нуклеинова киселина се изолира/открива в назофарингални проби.');
INSERT INTO `t_d_criteria` VALUES (5729,46,16,3,NULL,2,NULL,NULL,'unnumbered','machine','Индиректна диагноза (30.2.1.3): Ако е възможно, следва да се направи тест ELISA с използване на високо пречистен коклюшен токсин и референтни серуми на СЗО като стандарт. Резултатите трябва да се интерпретират в зависимост от ваксиналния статус по отношение на коклюш. Ако е имало ваксиниране през последните няколко години преди вземането на пробата, титърът на специфичните антитела срещу токсина на Bordetella pertussis може да е последица от предходната ваксинация или да е променен от нея.');
INSERT INTO `t_d_criteria` VALUES (5730,46,17,1,'3',1,NULL,NULL,NULL,'machine','Епидемиологични критерии:');
INSERT INTO `t_d_criteria` VALUES (5731,46,18,2,'3.1',2,NULL,NULL,'accepted-auto','machine','наличие на епидемична връзка - предаване от човек на човек.');
INSERT INTO `t_d_criteria` VALUES (5732,47,1,1,'1',1,NULL,NULL,NULL,'machine','Клинични критерии:');
INSERT INTO `t_d_criteria` VALUES (5733,47,2,2,'1.1',2,NULL,NULL,'accepted-auto','machine','всяко лице с ентеритен или ентероколитен синдром, напр. диария и коремни болки.');
INSERT INTO `t_d_criteria` VALUES (5734,47,3,1,'2',1,NULL,NULL,NULL,'machine','Лабораторни критерии:');
INSERT INTO `t_d_criteria` VALUES (5735,47,4,2,NULL,2,NULL,NULL,'accepted-auto','machine','Серотипизиране на E.coli по епидемични показания.');
INSERT INTO `t_d_criteria` VALUES (5736,47,5,1,'3',1,NULL,NULL,NULL,'machine','Епидемиологични критерии:');
INSERT INTO `t_d_criteria` VALUES (5737,47,6,2,'3.1',3,1,NULL,NULL,'machine','Поне една от следните епидемични връзки:');
INSERT INTO `t_d_criteria` VALUES (5738,47,7,3,'3.1.1',2,NULL,NULL,NULL,'machine','предаване от човек на човек;');
INSERT INTO `t_d_criteria` VALUES (5739,47,8,3,'3.1.2',2,NULL,NULL,NULL,'machine','наличие на общ източник;');
INSERT INTO `t_d_criteria` VALUES (5740,47,9,3,'3.1.3',2,NULL,NULL,NULL,'machine','консумиране на заразена храна/питейна вода;');
INSERT INTO `t_d_criteria` VALUES (5741,47,10,3,'3.1.4',2,NULL,NULL,NULL,'machine','експозиция в околната среда.');
INSERT INTO `t_d_criteria` VALUES (5742,52,1,1,'1',1,NULL,NULL,NULL,'machine','Клинични критерии:');
INSERT INTO `t_d_criteria` VALUES (5743,52,2,2,'1.1',2,NULL,NULL,'accepted-auto','machine','всяко лице със симптоми на възпаление на централната нервна система (напр. менингит, менингоенцефалит, енцефаломиелит, енцефалорадикулит).');
INSERT INTO `t_d_criteria` VALUES (5744,52,3,1,'2',1,NULL,NULL,NULL,'machine','Лабораторни критерии:');
INSERT INTO `t_d_criteria` VALUES (5745,52,4,2,'2.1',2,NULL,NULL,NULL,'machine','Лабораторни критерии за потвърждаване на случай:');
INSERT INTO `t_d_criteria` VALUES (5746,52,5,3,'2.1.1',3,1,NULL,NULL,'machine','Поне един от следните пет критерия:');
INSERT INTO `t_d_criteria` VALUES (5747,52,6,4,'2.1.1.1',2,NULL,NULL,NULL,'machine','специфични за TBE антитела IgM и IgG в кръвта;');
INSERT INTO `t_d_criteria` VALUES (5748,52,7,4,'2.1.1.2',2,NULL,NULL,NULL,'machine','специфични за TBE антитела IgM в цереброспиналния ликвор;');
INSERT INTO `t_d_criteria` VALUES (5749,52,8,4,'2.1.1.3',2,NULL,NULL,NULL,'machine','сероконверсия или четирикратно увеличение на специфичните за TBE антитела в двойни серумни проби;');
INSERT INTO `t_d_criteria` VALUES (5750,52,9,4,'2.1.1.4',2,NULL,NULL,NULL,'machine','откриване на нуклеинова киселина на вирус на TBE в клинична проба;');
INSERT INTO `t_d_criteria` VALUES (5751,52,10,4,'2.1.1.5',2,NULL,NULL,NULL,'machine','изолиране на TBE вирус от клинична проба.');
INSERT INTO `t_d_criteria` VALUES (5752,52,11,2,'2.2',2,NULL,NULL,NULL,'machine','Лабораторни критерии за вероятен случай: откриване на специфични за TBE антитела IgM в единична серумна проба.');
INSERT INTO `t_d_criteria` VALUES (5753,52,12,2,NULL,2,NULL,NULL,'unnumbered','machine','Серологичните резултати трябва да бъдат разглеждани в съответствие с ваксиналния статус и предходно излагане на други флавивирусни инфекции.');
INSERT INTO `t_d_criteria` VALUES (5754,52,13,2,NULL,2,NULL,NULL,'unnumbered','machine','Потвърдените случаи в такива ситуации трябва да бъдат валидирани чрез тест за вирусна неутрализация в серум или други равностойни тестове.');
INSERT INTO `t_d_criteria` VALUES (5755,52,14,1,'3',1,NULL,NULL,NULL,'machine','Епидемиологични критерии:');
INSERT INTO `t_d_criteria` VALUES (5756,52,15,2,'3.1',2,NULL,NULL,'accepted-auto','machine','излагане на въздействието на общ източник (непастьоризирани млечни продукти).');
INSERT INTO `t_d_criteria` VALUES (5757,54,1,1,'1',1,NULL,NULL,NULL,'machine','Клинични критерии:');
INSERT INTO `t_d_criteria` VALUES (5758,54,2,2,NULL,2,NULL,NULL,'accepted-auto','machine','Неврологични симптоми съгласно предложеното определение на случай, формулирано от Европейската федерация на неврологичните дружества (EFNS), без други видими причини. (EFNS guidelines on the diagnosis and management of European Lyme neuroborreliosis (Насоки на EFNS относно диагностицирането и овладяването на европейската лаймска невроборелиоза), European Journal of Neurology 17, 8 - 16: doi:10.1111/j.1468- 1331.2009.02862.x.)');
INSERT INTO `t_d_criteria` VALUES (5759,54,3,1,'2',1,NULL,NULL,NULL,'machine','Лабораторни критерии:');
INSERT INTO `t_d_criteria` VALUES (5760,54,4,2,'2.1',2,NULL,NULL,NULL,'machine','За потвърден случай:');
INSERT INTO `t_d_criteria` VALUES (5761,54,5,3,'2.1.1',2,NULL,NULL,NULL,'machine','плеоцитоза в ликвора');
INSERT INTO `t_d_criteria` VALUES (5762,54,6,4,'2.1.1.1',2,NULL,NULL,'operator-unclear','machine','доказателство за интратекално производство на антитела на лаймска борелиоза');
INSERT INTO `t_d_criteria` VALUES (5763,54,7,4,'2.1.1.2',2,NULL,'OR',NULL,'machine','изолиране на Borrelia burdgorferi s.l.');
INSERT INTO `t_d_criteria` VALUES (5764,54,8,4,'2.1.1.3',2,NULL,'OR',NULL,'machine','откриване на нуклеинова киселина в ликвора');
INSERT INTO `t_d_criteria` VALUES (5765,54,9,3,'2.1.2',2,NULL,'OR',NULL,'machine','откриване на IgG антитела на лаймска борелиоза в кръвна проба само за деца (на възраст под 18 години) с лицева парализа или друг краниален неврит и скорошна (преди по-малко от 2 месеца) проява на еритема мигранс.');
INSERT INTO `t_d_criteria` VALUES (5766,54,10,2,'2.2',2,NULL,NULL,NULL,'machine','За вероятен случай:');
INSERT INTO `t_d_criteria` VALUES (5767,54,11,3,'2.2.1',2,NULL,NULL,NULL,'machine','плеоцитоза в ликвора и положителен за лаймска борелиоза резултат от серологично изследване на ликвор');
INSERT INTO `t_d_criteria` VALUES (5768,54,12,3,'2.2.2',2,NULL,'OR',NULL,'machine','специфично интратекално производство на антитела на лаймска борелиоза.');
INSERT INTO `t_d_criteria` VALUES (5769,54,13,1,'3',1,NULL,NULL,NULL,'machine','Епидемиологични критерии: не е приложимо.');
INSERT INTO `t_d_criteria` VALUES (5770,55,1,1,'1',1,NULL,NULL,NULL,'machine','Клинични критерии:');
