INSERT INTO `t_d_criteria` VALUES (5774,55,5,3,'2.1.1',2,NULL,NULL,NULL,'machine','микроскопско или културелно доказване на паразита в пунктат от костен мозък, слезка, черен дроб, лимфен възел, кръв;');
INSERT INTO `t_d_criteria` VALUES (5775,55,6,3,'2.1.2',2,NULL,NULL,NULL,'machine','доказване на специфични антитела (РИФ, ELISA);');
INSERT INTO `t_d_criteria` VALUES (5776,55,7,3,'2.1.3',2,NULL,NULL,NULL,'machine','откриване на антиген и/или нуклеинова киселина на Leishmania в серум, кръв, пунктат от костен мозък.');
INSERT INTO `t_d_criteria` VALUES (5777,55,8,1,'3',1,NULL,NULL,NULL,'machine','Епидемиологични критерии: не е приложимо.');
