INSERT INTO `t_d_criteria` VALUES (5781,56,4,2,'2.1',2,NULL,NULL,NULL,'machine','Лабораторни критерии за потвърждаване на случай:');
INSERT INTO `t_d_criteria` VALUES (5782,56,5,3,'2.1.1',3,1,NULL,NULL,'machine','Поне един от следните три критерия:');
INSERT INTO `t_d_criteria` VALUES (5783,56,6,4,'2.1.1.1',2,NULL,NULL,NULL,'machine','изолиране на Legionella spp. от респираторен секрет или от каквото и да е място, което нормално е стерилно;');
INSERT INTO `t_d_criteria` VALUES (5784,56,7,4,'2.1.1.2',2,NULL,NULL,NULL,'machine','откриване на антиген на Legionella pneumophila в урината;');
INSERT INTO `t_d_criteria` VALUES (5785,56,8,4,'2.1.1.3',2,NULL,NULL,NULL,'machine','значително нарастване на титъра на специфичните антитела срещу Legionella pneumophila, серогрупа 1, в двойни серумни проби.');
