INSERT INTO `t_d_criteria` VALUES (5789,56,12,4,'2.2.1.2',2,NULL,NULL,NULL,'machine','откриване на нуклеинова киселина на Legionella spp. в респираторен секрет, белодробна тъкан или каквото и да е място, което нормално е стерилно;');
INSERT INTO `t_d_criteria` VALUES (5790,56,13,4,'2.2.1.3',2,NULL,NULL,NULL,'machine','значително нарастване на титъра на специфичните антитела срещу Legionella pneumophila, различни от серогрупа 1, или срещу други Legionella spp., в двойни серумни проби;');
INSERT INTO `t_d_criteria` VALUES (5791,56,14,4,'2.2.1.4',2,NULL,NULL,NULL,'machine','единичен висок титър на специфичните антитела срещу Legionella pneumophila, серогрупа 1, в серум.');
INSERT INTO `t_d_criteria` VALUES (5792,56,15,1,'3',1,NULL,NULL,NULL,'machine','Епидемиологични критерии: не е приложимо.');
INSERT INTO `t_d_criteria` VALUES (5793,60,1,1,'1',1,NULL,NULL,NULL,'machine','Клинични критерии:');
INSERT INTO `t_d_criteria` VALUES (5794,60,2,2,NULL,2,NULL,NULL,'accepted-auto','machine','Всяко лице със заболяване, което се характеризира с образуването на първичен афект на мястото, където е бил впит кърлеж - т. нар. \"таш ноар\" (окръглен инфилтрат, покрит с некротична коричка), повишаване на температурата, втрисане, главоболие, миалгия, кранио-фарингеален синдром, макуло-папулозен обрив, обхващащ цялото тяло, лицето, включително дланите и стъпалата.');
INSERT INTO `t_d_criteria` VALUES (5795,60,3,1,'2',1,NULL,NULL,NULL,'machine','Лабораторни критерии:');
