INSERT INTO `t_d_criteria` VALUES (5809,61,10,3,'2.1.2',2,NULL,NULL,NULL,'machine','откриване на нуклеинова киселина на Neisseria meningitidis в проба от място, което нормално е стерилно, или от пурпурични кожни лезии;');
INSERT INTO `t_d_criteria` VALUES (5810,61,11,3,'2.1.3',2,NULL,NULL,NULL,'machine','откриване на антиген на Neisseria meningitidis в ликвор;');
INSERT INTO `t_d_criteria` VALUES (5811,61,12,3,'2.1.4',2,NULL,NULL,NULL,'machine','откриване на грам-отрицателни диплококи в ликвор.');
INSERT INTO `t_d_criteria` VALUES (5812,61,13,1,'3',1,NULL,NULL,NULL,'machine','Епидемиологични критерии:');
INSERT INTO `t_d_criteria` VALUES (5813,61,14,2,'3.1',2,NULL,NULL,'accepted-auto','machine','епидемична връзка на предаване от човек на човек.');
INSERT INTO `t_d_criteria` VALUES (5814,62,1,1,'1',1,NULL,NULL,NULL,'machine','Клинични критерии:');
