INSERT INTO `t_d_criteria` VALUES (5819,62,6,3,'1.2.2',2,NULL,NULL,NULL,'machine','ринит;');
INSERT INTO `t_d_criteria` VALUES (5820,62,7,3,'1.2.3',2,NULL,NULL,NULL,'machine','конюнктивит.');
