INSERT INTO `t_d_criteria` VALUES (5825,62,12,3,'2.1.3',2,NULL,NULL,NULL,'machine','специфичен антитяло-отговор срещу вируса на морбили, характерен за остра инфекция, в серум или в слюнка;');
INSERT INTO `t_d_criteria` VALUES (5826,62,13,3,'2.1.4',2,NULL,NULL,NULL,'machine','откриване на антиген на вируса на морбили с тест DFA в клинична проба чрез специфични моноклонални антитела.');
INSERT INTO `t_d_criteria` VALUES (5827,62,14,3,NULL,2,NULL,NULL,'unnumbered','machine','Лабораторните резултати трябва да се интерпретират в зависимост от ваксиналния статус. При скорошно ваксиниране да се провери за наличието на див вирус.');
INSERT INTO `t_d_criteria` VALUES (5828,62,15,1,'3',1,NULL,NULL,NULL,'machine','Епидемиологични критерии:');
INSERT INTO `t_d_criteria` VALUES (5829,62,16,2,'3.1',2,NULL,NULL,'accepted-auto','machine','наличие на епидемична връзка - предаване от човек на човек.');
INSERT INTO `t_d_criteria` VALUES (5830,63,1,1,'1',1,NULL,NULL,NULL,'machine','Клинични критерии:');
INSERT INTO `t_d_criteria` VALUES (5831,63,2,2,NULL,2,NULL,NULL,'accepted-auto','machine','Всяко лице със заболяване с остро начало, обща интоксикация, главоболие, повишена температура, втрисане, болки зад гръдната кост, суха кашлица и рентгенови данни за пневмония.');
