INSERT INTO `t_d_criteria` VALUES (5835,63,6,3,'2.1.2',2,NULL,NULL,NULL,'machine','доказване на хламидиен антиген в материал от храчка;');
INSERT INTO `t_d_criteria` VALUES (5836,63,7,2,'2.2',2,NULL,NULL,NULL,'machine','Лабораторни критерии за вероятен случай:');
