INSERT INTO `t_d_criteria` VALUES (5844,64,1,1,'1',1,NULL,NULL,NULL,'machine','Клинични критерии:');
INSERT INTO `t_d_criteria` VALUES (5845,64,2,2,NULL,2,NULL,NULL,'accepted-auto','machine','Всяко лице със заболяване с внезапно начало, висока температура и разтрисане, силно изразен токсико-инфекциозен синдром, розеоло-петехиален обрив и промени в съзнанието (статус тифозус).');
