INSERT INTO `t_d_criteria` VALUES (5852,66,1,1,'1',1,NULL,NULL,NULL,'machine','Клинични критерии:');
INSERT INTO `t_d_criteria` VALUES (5853,66,2,2,NULL,2,NULL,NULL,'accepted-auto','machine','Всяко лице до 15 години със заболяване (включително синдром на Гилен-Баре и трансверзален миелит), което се характеризира с различна тежест, остро начало, с проява на слабост или парализа на група мускули, определена като \"вяла\" - мускулите са меки, отпуснати, с намален или липсващ тонус, без наличието на други явни причини за това (например травма). Случаите на преходна мускулна слабост не се съобщават.');
INSERT INTO `t_d_criteria` VALUES (5854,66,3,1,'2',1,NULL,NULL,NULL,'machine','Лабораторни критерии:');
