INSERT INTO `t_d_criteria` VALUES (5856,66,5,2,'2.2',2,NULL,NULL,NULL,'machine','позитивна серология, която може да се появи късно в течение на заболяването;');
INSERT INTO `t_d_criteria` VALUES (5857,66,6,2,'2.3',2,NULL,NULL,NULL,'machine','доказване на вирусни нуклеинови киселини.');
