INSERT INTO `t_d_criteria` VALUES (5870,68,13,3,'2.1.3',2,NULL,NULL,NULL,'machine','откриване на антитяло IgM срещу рубеола (на места, които се намират на етап пред елиминация, в някои ситуации може да се обмисли предприемане на допълнително изследване, за да се изключат фалшиви положителни резултати за стойностите на IgM (WHO Manual for the Laboratory Surveillance of Measles and Rubella Viruses, 2017);');
INSERT INTO `t_d_criteria` VALUES (5871,68,14,3,'2.1.4',2,NULL,NULL,NULL,'machine','сероконверсия на IgG срещу рубеола или значително повишение на титъра на IgG антителата срещу рубеола в двойни проби, изследвани успоредно.');
INSERT INTO `t_d_criteria` VALUES (5872,68,15,3,NULL,2,NULL,NULL,'unnumbered','machine','Лабораторните резултати трябва да се интерпретират в зависимост от ваксиналния статус (възможно персистиране на антитела IgM след ваксинацията).');
