INSERT INTO `t_d_case_rules` VALUES (46,15,3,'no_data',1,NULL,NULL,'Текстът по наредбата не е сведен до критерии: В. Потвърден: Всяко лице, което отговаря на лабораторните критерии за потвърждаване на случая. По време на епидемичен взрив: Всяко лице, което отговаря на клиничните критерии и при което съществува епидемична връзка.','machine');
