INSERT INTO `t_d_case_rules` VALUES (127,32,2,'no_data',1,NULL,NULL,'Текстът по наредбата не е сведен до критерии: Б. Вероятен случай: Всяко лице с положителен резултат от тест за грипен вирус A/H5 или A/H5N1, осъществен в лаборатория, различна от национална референтна лаборатория, участваща в Европейската мрежа от референтни лаборатории за грип при човека (CNRL).','machine');
