INSERT INTO `t_d_case_rules` VALUES (246,41,3,'no_data',1,NULL,NULL,'Текстът по наредбата не е сведен до критерии: В. Потвърден случай: Всяко лице, което отговаря на лабораторните критерии за потвърждаване на случая. Серологичните резултати трябва да се интерпретират в зависимост от предходно излагане на други флавивирусни инфекции и ваксиналния статус по отношение на флавивируси. Потвърдените случаи в такива ситуации трябва да бъдат валидирани чрез тест за вирусна неутрализация в серум или други равностойни тестове.','machine');
