INSERT INTO `t_d_case_rules` VALUES (459,69,2,'no_data',1,NULL,NULL,'Текстът по наредбата не е сведен до критерии: Б. Вероятен случай: Всяко мъртвородено дете или всяко кърмаче, което не е било изследвано или е било изследвано и лабораторните резултати са отрицателни и което отговаря на поне един от следните два критерия: епидемична връзка и поне един от клиничните критерии от категория (А) за вроден рубеолен синдром, отговаря на клиничните критерии за вроден рубеолен синдром.','machine');
INSERT INTO `t_d_case_rules` VALUES (460,69,3,'no_data',1,NULL,NULL,'Текстът по наредбата не е сведен до критерии: В. Потвърден случай: Всяко мъртвородено дете, което отговаря на лабораторните критерии, или всяко кърмаче, което отговаря на лабораторните критерии и на поне един от следните два критерия: епидемична връзка, поне един от клиничните критерии от категория (А) за вроден рубеолен синдром.','machine');
