INSERT INTO `t_d_case_rules` VALUES (509,8,3,'no_data',1,NULL,NULL,'Наредбата иска lab_confirmed, а в дървото няма такъв възел: В. Потвърден случай: Лице, което отговаря на лабораторните критерии за потвърден случай. Забележка. Серологичните резултати трябва да се интерпретират в зависимост от предходно излагане на други флавивирусни инфекции и ваксиналния статус по отношение на флавивируси. Потвърдените случаи в такива ситуации трябва да бъдат валидирани чрез тест за вирусна неутрализация в серум или други равностойни тестове.','machine');
INSERT INTO `t_d_case_rules` VALUES (648,75,1,'rule',1,'в период между епидемии','1:1 AND 3:1',NULL,'manual');
INSERT INTO `t_d_case_rules` VALUES (649,75,1,'rule',1,'по време на епидемия','1:1',NULL,'manual');
INSERT INTO `t_d_case_rules` VALUES (650,75,2,'rule',1,'в период между епидемии','1:1 AND 3:1 AND 2.2:1','Наредбата иска лабораторните критерии ЗА ВЕРОЯТЕН СЛУЧАЙ (54.2.2), а не тези за потвърждаване (54.2.1). Затова членът сочи пътя 2.2, не цялата категория 2.','manual');
INSERT INTO `t_d_case_rules` VALUES (651,75,2,'rule',1,'по време на епидемия','1:1 AND 3:1',NULL,'manual');
INSERT INTO `t_d_case_rules` VALUES (652,75,3,'rule',1,'в период между епидемии','1:1 AND 2.1:1','Наредбата дава два потвърдени случая - В \"на национално равнище\" и Г (референтна лаборатория на СЗО). Разликата е коя лаборатория е изследвала, а това не е критерий в дървото, затова двата са едно правило.','manual');
INSERT INTO `t_d_case_rules` VALUES (653,75,3,'rule',1,'по време на епидемия','1:1 AND 2.1:1','Наредбата дава два потвърдени случая - В \"на национално равнище\" и Г (референтна лаборатория на СЗО). Разликата е коя лаборатория е изследвала, а това не е критерий в дървото, затова двата са едно правило.','manual');
