INSERT INTO `t_patient_notification_criteria` VALUES (584,344,2,NULL,'Всяко лице със следните симптоми: остро начало, повишена температура, умерено увредено общо състояние и циклично развиващ се, придружен със сърбеж псевдополиморфен обрив (макули, папули, везикули, крусти). Обривът е разпространен по тялото, лицето и крайниците, задължително по окосмената част на главата и рядко се наблюдава по дланите и стъпалата. Единични обривни елементи се наблюдават и по лигавиците.');
