INSERT INTO `t_patient_notification_criteria` VALUES (3506,2021,2,NULL,'Всяко лице до 15 години със заболяване (включително синдром на Гилен-Баре и трансверзален миелит), което се характеризира с различна тежест, остро начало, с проява на слабост или парализа на група мускули, определена като \"вяла\" - мускулите са меки, отпуснати, с намален или липсващ тонус, без наличието на други явни причини за това (например травма). Случаите на преходна мускулна слабост не се съобщават.');
INSERT INTO `t_patient_notification_criteria` VALUES (3507,2022,2,NULL,'Всяко лице до 15 години със заболяване (включително синдром на Гилен-Баре и трансверзален миелит), което се характеризира с различна тежест, остро начало, с проява на слабост или парализа на група мускули, определена като \"вяла\" - мускулите са меки, отпуснати, с намален или липсващ тонус, без наличието на други явни причини за това (например травма). Случаите на преходна мускулна слабост не се съобщават.');
