  `is_group` tinyint(4) NOT NULL DEFAULT 0 COMMENT '0-no group (default); 1-group',
  `type` tinyint(4) NOT NULL DEFAULT 1 COMMENT '1 - Appendix 1 (diseases); 2 - Appendix 1a (cases)',
