DROP TABLE IF EXISTS `t_d_criteria`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8mb4 */;
CREATE TABLE `t_d_criteria` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `d_id` int(11) NOT NULL,
  `seq` smallint(5) unsigned DEFAULT NULL COMMENT 'row sequence',
  `depth` bigint(20) DEFAULT NULL COMMENT 'criteria depth (1.; 1.1., etc.)',
  `p3_path` varchar(60) DEFAULT NULL COMMENT 'номерационен път по Приложение № 3, спрямо раздела на болестта (напр. 2.2 = 54.2.2)',
  `type` tinyint(1) DEFAULT NULL COMMENT '1-category; 2-criterion; 3-condition; 4-other',
  `condition_require` tinyint(1) DEFAULT NULL COMMENT 'if type "condition" - how many selected children are required',
  `join_op` enum('AND','OR') DEFAULT NULL COMMENT 'операторът, който свързва този ред с предходния на същото ниво; идва от самостоятелно "и"/"или" в текста',
  `flag` varchar(40) DEFAULT NULL COMMENT 'бележка от преобразуването: unnumbered - ред без номерация; operator-unclear - не е ясно какво свързва операторът',
  `origin` enum('machine','manual') NOT NULL DEFAULT 'machine' COMMENT 'machine - произведен от преобразуването на описанието; manual - редактиран на ръка',
  `name` varchar(500) NOT NULL,
  PRIMARY KEY (`id`),
  KEY `d_seq` (`d_id`,`seq`)
) ENGINE=InnoDB AUTO_INCREMENT=7630 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Дефиниции на случаите по Приложение № 3 към Наредба № 21, последно изм. ДВ бр. 35 от 14.04.2026';
/*!40101 SET character_set_client = @saved_cs_client */;

