DROP TABLE IF EXISTS `t_d_case_rules`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8mb4 */;
CREATE TABLE `t_d_case_rules` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `d_id` int(11) NOT NULL COMMENT 'болест',
  `degree_id` int(11) NOT NULL COMMENT 't_d_degree: 1 възможен, 2 вероятен, 3 потвърден',
  `status` enum('rule','not_applicable','no_data') NOT NULL DEFAULT 'rule' COMMENT 'rule - има правило; not_applicable - наредбата обявява класа за неприложим; no_data - няма данни',
  `seq` tinyint(3) unsigned NOT NULL DEFAULT 1 COMMENT 'алтернатива в класа; алтернативите се свързват с ИЛИ',
  `context` varchar(100) DEFAULT NULL COMMENT 'дословният контекст от наредбата, когато класификацията е в повече от един контекст',
  `expression` varchar(255) DEFAULT NULL COMMENT 'членове през AND: <номер на категория>:<минимум отметки>; NULL, когато няма правило',
  `note` varchar(500) DEFAULT NULL COMMENT 'какво в текста на наредбата не е сведено до критерии и защо',
  `origin` enum('machine','manual') NOT NULL DEFAULT 'machine' COMMENT 'machine - предложен от преобразуването на описанието; manual - въведен или редактиран на ръка',
  PRIMARY KEY (`id`),
  KEY `d_degree` (`d_id`,`degree_id`,`seq`)
) ENGINE=InnoDB AUTO_INCREMENT=729 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Кои категории критерии и с колко отметки правят случая възможен/вероятен/потвърден. Общите определения са по Приложение № 2, конкретното правило за всяка болест - по раздела "Класификация на случаите" в Приложение № 3. Редакция изм. ДВ бр. 35 от 14.04.2026';
/*!40101 SET character_set_client = @saved_cs_client */;

