CREATE TABLE `t_patient_notifications` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `p_id` int(11) NOT NULL COMMENT 't_patients.id',
  `gp_id` int(11) NOT NULL COMMENT 't_gps.id - the general practitioner',
  `disease_id` int(11) NOT NULL COMMENT 't_diseases.id',
  `degree_id` int(11) NOT NULL COMMENT 't_d_degree.id: 1 possible, 2 probable, 3 confirmed',
  `field_created` timestamp NOT NULL DEFAULT current_timestamp() COMMENT 'When the notice was saved; the statistics filter on it',
  `case_context` varchar(255) DEFAULT NULL COMMENT 'the section of Appendix 3 the class was decided under, when the disease has more than one',
  `rule_expression` varchar(255) DEFAULT NULL COMMENT 'the expression that held, e.g. "1:1 AND 3:1"; copied, not referenced',
  `rule_status` varchar(32) DEFAULT NULL COMMENT 'rule | not_applicable | no_data - why there is or is not a class',
  `d_code` varchar(32) DEFAULT NULL COMMENT 'the code of the disease by Appendix 1 as it stood at the time',
  `d_name` varchar(1024) DEFAULT NULL COMMENT 'the name of the disease as it stood at the time',
  `issued_by` int(11) DEFAULT NULL COMMENT 't_users.id of the doctor who pronounced the class - no FK, t_users is a login table',
  PRIMARY KEY (`id`),
